-- Runs automatically the FIRST time the Docker database starts (empty volume).
-- Creates the question table and fills it with sample questions.

CREATE TABLE IF NOT EXISTS question (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question_title   VARCHAR(255),
    option1          VARCHAR(255),
    option2          VARCHAR(255),
    option3          VARCHAR(255),
    option4          VARCHAR(255),
    right_answer     VARCHAR(255),
    difficulty_level  VARCHAR(255),
    category         VARCHAR(255)
    );

